    ; Pxl-On at (P0,P1)
    MOV VX,P0
    MOV VY,P1
    MOV P0,P2
    SWRITE P0
    ; Pxl-On
    ; Load X into P2
    MOV P2,[0x202E]
    ADD P2,2
    ; Load Y into P1
    MOV P1,[0x2030]
    MOV P0,248
    ; Pxl-On at (P2,P1)
    MOV VX,P2
    MOV VY,P1
    MOV P0,P0
    SWRITE P0
    ; Pxl-On
    ; Load X into P0
    MOV P0,[0x202E]
    ADD P0,3
    ; Load Y into P1
    MOV P1,[0x2030]
    MOV P2,252
    ; Pxl-On at (P0,P1)
    MOV VX,P0
    MOV VY,P1
    MOV P0,P2
    SWRITE P0
    ; Pause - wait for key press
pause_loop:
    KEYSTAT P0
    CMP P0,0
    JZ pause_loop
    KEYIN P0

; Program end - infinite loop to keep display visible
halt:
JMP halt
ORG 0x2000
